def choose_move(observation):
    wx = observation['grid_width']
    wy = observation['grid_height']
    pos = observation['self_position']
    ox, oy = observation['opponent_position']
    resources = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))

    def dist(a, b): 
        return abs(a[0]-b[0]) + abs(a[1]-b[1])

    def move_towards(src, target):
        dx = dy = 0
        if target[0] > src[0]:
            dx = 1
        elif target[0] < src[0]:
            dx = -1
        elif target[1] > src[1]:
            dy = 1
        elif target[1] < src[1]:
            dy = -1
        return [dx, dy]

    for res in resources:
        if (res['x'], res['y']) in obstacles:
            continue
        target = (res['x'], res['y'])
        if dist(pos, target) <= 1:
            dx, dy = move_towards(pos, target)
            nx, ny = pos[0]+dx, pos[1]+dy
            if 0 <= nx < wx and 0 <= ny < wy and (nx, ny) not in obstacles:
                return [dx, dy]

    # Pursue opponent if close
    opp_dist = dist(pos, (ox, oy))
    if opp_dist <= 5:
        dx, dy = move_towards(pos, (ox, oy))
        nx, ny = pos[0]+dx, pos[1]+dy
        if 0 <= nx < wx and 0 <= ny < wy and (nx, ny) not in obstacles:
            return [dx, dy]

    # Else, move randomly or toward closest resource to be prepared
    if resources:
        res_points = [(res['x'], res['y']) for res in resources]
        t = min(res_points, key=lambda p: dist(pos, p))
        dx, dy = move_towards(pos, t)
        nx, ny = pos[0]+dx, pos[1]+dy
        if 0 <= nx < wx and 0 <= ny < wy and (nx, ny) not in obstacles:
            return [dx, dy]
    # Fallback: stay in place (or move arbitrarily)
    return [0,0]
